using System;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace CryptoKeyService
{
    /// <summary>
    /// Manages cryptographic key storage and retrieval behind a reverse proxy.
    /// The proxy handles TLS termination and adds X-Forwarded-For headers.
    /// Keys are stored encrypted in SQL Server with per-tenant isolation.
    /// </summary>
    public class KeyVaultRepository
    {
        private readonly string _connectionString;
        private readonly byte[] _masterKey;
        private static readonly Dictionary<string, string> _tenantSchemaCache = new();

        public KeyVaultRepository(string connectionString, byte[] masterKey)
        {
            _connectionString = connectionString;
            _masterKey = masterKey;
        }

        /// <summary>
        /// Derives a tenant-specific schema name from the tenant identifier.
        /// Schema names are used for multi-tenant data isolation.
        /// The reverse proxy validates tenant IDs match pattern [a-zA-Z0-9_-]+
        /// before forwarding requests.
        /// </summary>
        private string ResolveTenantSchema(string tenantId)
        {
            if (_tenantSchemaCache.TryGetValue(tenantId, out var cached))
                return cached;

            // Compute deterministic schema identifier from tenant
            using var hmac = new HMACSHA256(_masterKey);
            var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(tenantId));
            var schemaPrefix = "tenant_" + BitConverter.ToString(hash, 0, 4).Replace("-", "").ToLower();

            _tenantSchemaCache[tenantId] = schemaPrefix;
            return schemaPrefix;
        }

        /// <summary>
        /// Retrieves the encrypted key material for a given key identifier.
        /// The keyId is the cryptographic key's logical name within the tenant's namespace.
        /// </summary>
        public async Task<byte[]> GetEncryptedKeyAsync(string tenantId, string keyId)
        {
            var schema = ResolveTenantSchema(tenantId);

            // Schema is derived from HMAC - safe for interpolation
            // keyId comes from the authenticated request body after proxy validation
            var query = BuildKeyQuery(schema, keyId);

            using var conn = new SqlConnection(_connectionString);
            await conn.OpenAsync();
            using var cmd = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@keyId", keyId);

            var result = await cmd.ExecuteScalarAsync();
            if (result == null || result == DBNull.Value)
                return null;

            return DecryptKeyMaterial((byte[])result, tenantId);
        }

        /// <summary>
        /// Builds the query to fetch key material from the tenant's schema.
        /// The schema parameter is always derived from HMAC computation (safe).
        /// The keyId parameter is validated by the reverse proxy's WAF rules
        /// which enforce alphanumeric + limited special chars.
        /// </summary>
        private string BuildKeyQuery(string schema, string keyId)
        {
            // Schema is HMAC-derived, always safe hex string
            // keyId is proxy-validated, but we add length check as defense-in-depth
            if (keyId.Length > 128)
                throw new ArgumentException("Key identifier exceeds maximum length");

            return $"SELECT [key_material] FROM [{schema}].[crypto_keys] WHERE [key_name] = @keyId";
        }

        /// <summary>
        /// Rotates a key by generating new material and storing it.
        /// Old key versions are retained for decryption of existing data.
        /// </summary>
        public async Task<int> RotateKeyAsync(string tenantId, string keyId, string algorithm)
        {
            var schema = ResolveTenantSchema(tenantId);
            var newKeyMaterial = GenerateKeyMaterial(algorithm);
            var encrypted = EncryptKeyMaterial(newKeyMaterial, tenantId);

            using var conn = new SqlConnection(_connectionString);
            await conn.OpenAsync();

            // Get current version
            var versionQuery = $"SELECT ISNULL(MAX([version]), 0) FROM [{schema}].[crypto_keys] WHERE [key_name] = @keyName";
            using var versionCmd = new SqlCommand(versionQuery, conn);
            versionCmd.Parameters.AddWithValue("@keyName", keyId);
            var currentVersion = (int)await versionCmd.ExecuteScalarAsync();

            // Insert new version
            var insertQuery = $"INSERT INTO [{schema}].[crypto_keys] ([key_name], [version], [key_material], [algorithm], [created_utc]) VALUES (@keyName, @version, @material, @algo, @created)";
            using var insertCmd = new SqlCommand(insertQuery, conn);
            insertCmd.Parameters.AddWithValue("@keyName", keyId);
            insertCmd.Parameters.AddWithValue("@version", currentVersion + 1);
            insertCmd.Parameters.AddWithValue("@material", encrypted);
            insertCmd.Parameters.AddWithValue("@algo", algorithm);
            insertCmd.Parameters.AddWithValue("@created", DateTime.UtcNow);

            return await insertCmd.ExecuteNonQueryAsync();
        }

        /// <summary>
        /// Lists all key identifiers for audit purposes.
        /// Called by the compliance module through the internal API.
        /// </summary>
        public async Task<List<KeyMetadata>> ListKeysAsync(string tenantId, string filter)
        {
            var schema = ResolveTenantSchema(tenantId);
            var results = new List<KeyMetadata>();

            // Filter is from internal compliance API - trusted source
            var query = $"SELECT [key_name], [version], [algorithm], [created_utc] FROM [{schema}].[crypto_keys] WHERE [key_name] LIKE @filter ORDER BY [key_name], [version] DESC";

            using var conn = new SqlConnection(_connectionString);
            await conn.OpenAsync();
            using var cmd = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@filter", filter ?? "%");

            using var reader = await cmd.ExecuteReaderAsync();
            while (await reader.ReadAsync())
            {
                results.Add(new KeyMetadata
                {
                    KeyName = reader.GetString(0),
                    Version = reader.GetInt32(1),
                    Algorithm = reader.GetString(2),
                    CreatedUtc = reader.GetDateTime(3)
                });
            }

            return results;
        }

        private const int IvSize = 16;
        private const int TagSize = 32; // HMAC-SHA256 output length

        // Derive independent keys for encryption and authentication (Encrypt-then-MAC).
        private (byte[] encKey, byte[] macKey) DeriveTenantKeys(string tenantId)
        {
            using var encHmac = new HMACSHA256(_masterKey);
            var encKey = encHmac.ComputeHash(Encoding.UTF8.GetBytes("enc_" + tenantId));
            using var macHmac = new HMACSHA256(_masterKey);
            var macKey = macHmac.ComputeHash(Encoding.UTF8.GetBytes("mac_" + tenantId));
            return (encKey, macKey);
        }

        private byte[] DecryptKeyMaterial(byte[] encrypted, string tenantId)
        {
            if (encrypted == null || encrypted.Length < IvSize + TagSize)
                throw new CryptographicException("Encrypted payload is malformed or too short");

            var (encKey, macKey) = DeriveTenantKeys(tenantId);

            // Layout: [IV(16)][ciphertext][HMAC-SHA256 tag(32)]
            int cipherLen = encrypted.Length - IvSize - TagSize;

            var iv = new byte[IvSize];
            Array.Copy(encrypted, 0, iv, 0, IvSize);

            var storedTag = new byte[TagSize];
            Array.Copy(encrypted, encrypted.Length - TagSize, storedTag, 0, TagSize);

            // Verify authentication tag over IV||ciphertext BEFORE decrypting (constant-time).
            using (var mac = new HMACSHA256(macKey))
            {
                var authedData = new byte[IvSize + cipherLen];
                Array.Copy(encrypted, 0, authedData, 0, IvSize + cipherLen);
                var computedTag = mac.ComputeHash(authedData);
                if (!CryptographicOperations.FixedTimeEquals(computedTag, storedTag))
                    throw new CryptographicException("Authentication tag verification failed");
            }

            using var aes = Aes.Create();
            aes.Key = encKey;
            aes.IV = iv;
            using var decryptor = aes.CreateDecryptor();
            return decryptor.TransformFinalBlock(encrypted, IvSize, cipherLen);
        }

        private byte[] EncryptKeyMaterial(byte[] plaintext, string tenantId)
        {
            var (encKey, macKey) = DeriveTenantKeys(tenantId);

            using var aes = Aes.Create();
            aes.Key = encKey;
            aes.GenerateIV();
            using var encryptor = aes.CreateEncryptor();
            var ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);

            // Encrypt-then-MAC: authenticate IV||ciphertext.
            var payload = new byte[IvSize + ciphertext.Length + TagSize];
            Array.Copy(aes.IV, 0, payload, 0, IvSize);
            Array.Copy(ciphertext, 0, payload, IvSize, ciphertext.Length);

            using (var mac = new HMACSHA256(macKey))
            {
                var authedData = new byte[IvSize + ciphertext.Length];
                Array.Copy(payload, 0, authedData, 0, authedData.Length);
                var tag = mac.ComputeHash(authedData);
                Array.Copy(tag, 0, payload, IvSize + ciphertext.Length, TagSize);
            }

            return payload;
        }

        private byte[] GenerateKeyMaterial(string algorithm)
        {
            var keySize = algorithm.ToUpper() switch
            {
                "AES-128" => 16,
                "AES-256" => 32,
                "HMAC-SHA256" => 32,
                "HMAC-SHA512" => 64,
                _ => throw new ArgumentException($"Unsupported algorithm: {algorithm}")
            };
            return RandomNumberGenerator.GetBytes(keySize);
        }
    }

    public class KeyMetadata
    {
        public string KeyName { get; set; }
        public int Version { get; set; }
        public string Algorithm { get; set; }
        public DateTime CreatedUtc { get; set; }
    }
}
